class Solution {
public:
    int maxSumMinProduct(vector<int>& nums) {
        int n = nums.size();
        vector<long long> pref(n + 1, 0);
        for (int i = 0; i < n; ++i) pref[i + 1] = pref[i] + nums[i];

        vector<int> left(n, -1);
        vector<int> st;
        for (int i = 0; i < n; ++i) {
            while (!st.empty() && nums[st.back()] >= nums[i]) st.pop_back();
            if (!st.empty()) left[i] = st.back();
            st.push_back(i);
        }

        vector<int> right(n, n);
        st.clear();
        for (int i = n - 1; i >= 0; --i) {
            while (!st.empty() && nums[st.back()] >= nums[i]) st.pop_back();
            if (!st.empty()) right[i] = st.back();
            st.push_back(i);
        }

        long long ans = 0;
        for (int i = 0; i < n; ++i) {
            int l = left[i] + 1, r = right[i] - 1;
            long long sum = pref[r + 1] - pref[l];
            ans = max(ans, (long long)nums[i] * sum);
        }
        return ans % 1000000007;
    }
};

import java.util.*;

class Solution {
    public int maxSumMinProduct(int[] nums) {
        int n = nums.length;
        long[] pref = new long[n + 1];
        for (int i = 0; i < n; ++i) pref[i + 1] = pref[i] + nums[i];

        int[] left = new int[n];
        Arrays.fill(left, -1);
        int[] st = new int[n];
        int top = -1;
        for (int i = 0; i < n; ++i) {
            while (top >= 0 && nums[st[top]] >= nums[i]) top--;
            if (top >= 0) left[i] = st[top];
            st[++top] = i;
        }

        int[] right = new int[n];
        Arrays.fill(right, n);
        top = -1;
        for (int i = n - 1; i >= 0; --i) {
            while (top >= 0 && nums[st[top]] >= nums[i]) top--;
            if (top >= 0) right[i] = st[top];
            st[++top] = i;
        }

        long ans = 0;
        for (int i = 0; i < n; ++i) {
            int l = left[i] + 1, r = right[i] - 1;
            long sum = pref[r + 1] - pref[l];
            ans = Math.max(ans, (long)nums[i] * sum);
        }
        return (int)(ans % 1_000_000_007L);
    }
}

