var maxSumMinProduct = function(nums) {
    const n = nums.length;
    const pref = Array(n + 1).fill(0n);
    for (let i = 0; i < n; ++i) pref[i + 1] = pref[i] + BigInt(nums[i]);

    const left = Array(n).fill(-1);
    const st1 = [];
    for (let i = 0; i < n; ++i) {
        while (st1.length > 0 && nums[st1[st1.length - 1]] >= nums[i]) st1.pop();
        if (st1.length > 0) left[i] = st1[st1.length - 1];
        st1.push(i);
    }

    const right = Array(n).fill(n);
    const st2 = [];
    for (let i = n - 1; i >= 0; --i) {
        while (st2.length > 0 && nums[st2[st2.length - 1]] >= nums[i]) st2.pop();
        if (st2.length > 0) right[i] = st2[st2.length - 1];
        st2.push(i);
    }

    let ans = 0n;
    for (let i = 0; i < n; ++i) {
        const l = left[i] + 1, r = right[i] - 1;
        const sum = pref[r + 1] - pref[l];
        const prod = BigInt(nums[i]) * sum;
        if (prod > ans) ans = prod;
    }
    return Number(ans % 1000000007n);
};
